patches.before:
plugins {
    id "com.android.application"
}

def cloudOrigin = providers.environmentVariable("SCENEVIBE_CLOUD_ORIGIN").orElse("").get()
if (cloudOrigin && !(cloudOrigin ==~ /https:\/\/[^\/:?#]+/)) {
    throw new GradleException("SCENEVIBE_CLOUD_ORIGIN must be an exact HTTPS origin on port 443")
}

def enableLanDev = providers.environmentVariable("SCENEVIBE_ENABLE_LAN_DEV").orElse("false").get()
def enableLanDevLiteral = enableLanDev.equalsIgnoreCase("true") ? "true" : "false"

android {
    buildFeatures { buildConfig true }
    namespace "com.scenevibe.tvcompanionpoc"
    compileSdk 35

    defaultConfig {
        applicationId "com.scenevibe.tvcompanionpoc"
        minSdk 26
        targetSdk 35
        versionCode 12
        versionName "0.8.2-tv-release-hardening"
        buildConfigField "String", "CLOUD_ORIGIN", "\"${cloudOrigin}\""
        buildConfigField "boolean", "ENABLE_LAN_DEV", "${enableLanDevLiteral}"
    }

    buildTypes {
        // Explicit production RELEASE variant. The POC intentionally keeps minify
        // and resource shrinking OFF so the qualified 0.8.1 runtime behavior stays
        // byte-for-byte unchanged except for the debuggable flag and signing. No
        // signingConfig is embedded here: the real release signature is applied
        // post-build by apksigner in CI using GitHub secrets, so no key material is
        // ever required at Gradle configure time. assembleRelease therefore emits an
        // unsigned, non-debuggable APK (app-release-unsigned.apk).
        release {
            debuggable false
            minifyEnabled false
            shrinkResources false
            signingConfig null
        }
    }

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_17
        targetCompatibility JavaVersion.VERSION_17
    }

    testOptions { unitTests.returnDefaultValues = true }
}

dependencies {
    testImplementation "junit:junit:4.13.2"
    testImplementation "org.json:json:20240303"
}

