}

def enableLanDev = providers.environmentVariable("SCENEVIBE_ENABLE_LAN_DEV").orElse("false").get()
def enableLanDevLiteral = enableLanDev.equalsIgnoreCase("true") ? "true" : "false"

// A named qualification build is opt-in and must never share the LAN writer.
def m6Qualification = providers.environmentVariable("SCENEVIBE_M6_QUALIFICATION").orElse("").get()
if (m6Qualification && m6Qualification != "m6-qualification") {
    throw new GradleException("SCENEVIBE_M6_QUALIFICATION must be exactly m6-qualification")
}
